const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // --- Core Requirements ---
  // The question is for a future date (Aug 6, 2024). GEE contains historical data.
  // To provide a workable example, the analysis will be performed for the same date in the most recent available year, 2023.
  // The local time 1:40 PM in Paris (CEST, UTC+2) is 11:40 UTC.
  // The MODIS Aqua satellite (MYD11_L2) has an overpass time around 1:30 PM local, making it the most suitable sensor.

  // 1. Geometry & Time Definitions
  const paris = ee.Geometry.Point([2.3522, 48.8566]);
  const areaOfInterest = paris.buffer(500); // 500m buffer around the point
  const analysisDate = '2023-08-06';
  const temperatureThresholdCelsius = 32.0;

  // 2. Data Acquisition & Check
  // Using MODIS Aqua L2 Swath LST data, which is closest to the requested time of day.
  const lstCollection = ee.ImageCollection('MODIS/MYD11_L2')
    .filterDate(analysisDate)
    .filterBounds(areaOfInterest);

  const collectionSize = lstCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log('Evidence: No MODIS images found for Paris on 2023-08-06.');
    console.log('A: No');
    return;
  }

  // 3. Processing
  // Select the daytime LST band and mosaic the collection (handles multiple swaths if present)
  const lstImage = lstCollection.select('LST_Day_1km').mosaic();

  // Convert from Kelvin to Celsius. The scale factor is 0.02.
  const lstCelsius = lstImage.multiply(0.02).subtract(273.15);

  // 4. Calculation
  const stats = lstCelsius.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: areaOfInterest,
    scale: 1000, // Native resolution of the LST band
    maxPixels: 1e9
  });

  const meanTemp = stats.get('LST_Day_1km_mean').getInfo();
  const pixelCount = stats.get('LST_Day_1km_count').getInfo();

  // 5. Validation & Final Answer
  console.log(`Date Analyzed: ${analysisDate} (for requested future date 2024-08-06)`);
  console.log(`Sensor: MODIS Aqua (MYD11_L2)`);

  if (pixelCount === 0) {
    console.log('Evidence: Images exist but no valid pixels found in the area of interest.');
    console.log('C2');
    return;
  }

  if (meanTemp === null || typeof meanTemp === 'undefined') {
    console.log('Evidence: Failed to calculate mean temperature.');
    console.log(`Pixel Count: ${pixelCount}`);
    console.log('C3');
    return;
  }

  console.log(`Evidence: Mean Land Surface Temperature in Paris: ${meanTemp.toFixed(2)} C`);
  console.log(`Evidence: Valid Pixel Count: ${pixelCount}`);
  console.log(`Evidence: Temperature Threshold: ${temperatureThresholdCelsius.toFixed(2)} C`);

  if (meanTemp > temperatureThresholdCelsius) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error('An error occurred during initialization or analysis:');
    console.error(e);
    console.log('D');
  }
}

initEE();
